#!/usr/bin/env bash
# Fails when hand-written Markdown contains an em-dash (U+2014), which the
# writing style for these repositories forbids. Files under .entire/ and
# .claude/ are generated by those tools, so they are not checked.
set -euo pipefail

readonly em_dash=$'\xe2\x80\x94'

if git grep -n -I -F -e "$em_dash" -- '*.md' ':(exclude).entire/' ':(exclude).claude/'; then
  echo "Replace the em-dashes above with a comma, colon, parentheses, or a new sentence." >&2
  exit 1
fi
echo "No em-dashes in hand-written Markdown."
